import type { SampleCharacterArc } from "./sample-character-arcs.js";

/** Individually authored episodes. Null bindings are intentional text-only entries. */
export const OCEAN_CHARACTER_ARCS: readonly SampleCharacterArc[] = [
  {
    characterId: "nell-pelagic", identityNameBase: "Nell Pelagic", platform: "rss",
    bio: "A dumbo octopus who can leave any argument vertically, and usually does.",
    location: { name: "Deep Gulf of Mexico, approximate benthic home", coordinates: { lat: 26.1, lng: -91.5 } },
    episodes: [
      { subject: "dumbo octopus", mediaSha1: null, theme: "movement", title: "A small upward objection", body: "A cucumber was coming straight toward my resting place. I lifted off the bottom to let it through. It stopped beneath me.\n\nI waited. It ate. I waited while it ate somewhere else without leaving the area directly beneath me. Eventually I landed beside it, which required considerably more effort than moving aside in the first place.\n\nIt has a perfectly ordinary face for an animal that has defeated me." },
      { subject: "dumbo octopus", mediaSha1: null, theme: "feeding", title: "The scoop", body: "I spread my arms over a promising patch and settled down around it. A little crustacean slipped out before I closed the gap. I watched it go, then examined the patch very carefully.\n\nThere were others. Smaller, but others. I ate and lifted off again.\n\nThe escaped one was sitting on the ridge ahead. I went around. I refuse to give it a second impressive story about itself." },
      { subject: "dumbo octopus", mediaSha1: null, theme: "wonder", title: "Snow with no winter", body: "Something pale kept falling. A scrap landed on my arm, broke apart, and drifted toward the bottom. Another followed it.\n\nI lifted away from the little shower. Below me, small animals were moving through what had already settled. I descended toward them, more interested in the gathering than the invitation.\n\nOne scrap stayed on my head throughout. I could feel it and could not quite reach it." },
      { subject: "dumbo octopus", mediaSha1: null, theme: "social", title: "A rather long silence", body: "Another octopus came into view. Neither of us had much speed to lose, but we slowed anyway.\n\nI folded one arm. It folded two. We hovered there until the effort began to feel ridiculous. Then we passed, each making a generous curve that the other had already allowed for.\n\nBehind me, it settled on the bottom. I found somewhere farther on. For a while I kept my fins moving after I no longer needed to." },
      { subject: "dumbo octopus", mediaSha1: "93eaea49a5ea54cfbe91c1004ac9a24a66e271b0", theme: "danger", title: "Too much morning", body: "A light came across the bottom. Brighter than any animal I know, and terribly persistent. I rose. It rose with me.\n\nI curled my arms and turned away, discovering that there is no flattering direction from which to flee an entire sunrise.\n\nEventually it went elsewhere. I descended slowly. The cucumber below had continued eating throughout. I landed behind it." },
      { subject: "dumbo octopus", mediaSha1: null, theme: "movement", title: "The return was uphill", body: "I followed a slope down because it looked easier than going up. It was.\n\nAt the bottom I found a bare hollow and realized that the nice patch I had left was now above me. I could see enough of the slope to recognize my own poor judgment, which did not make climbing it cheaper.\n\nI stopped halfway and fed. If I rest over something edible, I can call this a different trip." },
      { subject: "dumbo octopus", mediaSha1: null, theme: "social", title: "An unnecessarily grand arrival", body: "The other octopus was feeding below the ridge. I rose high enough to approach from above, with my arms folded neatly and both fins moving together.\n\nI meant to land beside it. A small crustacean moved beneath my left arm as I descended. I reached, tilted, and landed on that side in a puff of sediment.\n\nWhen the water cleared, the other octopus was still feeding. It may not have noticed. I hope it noticed the first part." },
      { subject: "dumbo octopus", mediaSha1: null, theme: "feeding", title: "The patch beneath me", body: "I lifted to choose somewhere better to eat and noticed small tracks under the place I had been resting.\n\nI landed again, spread my arms, and fed. A whole little meal had been happening beneath my complaint.\n\nThe cucumber approached from the side. This time I stayed put until I was finished. Then I rose with what I hoped looked like the unhurried confidence of somebody who had meant to share all along." },
      { subject: "dumbo octopus", mediaSha1: null, theme: "wonder", title: "The falling piece", body: "A scrap much larger than the usual flakes turned slowly above me. I followed it down. It brushed one arm, spun, and continued.\n\nFor a few moments I could feel its weight without having to carry it. Then the bottom took it. Little animals were already beginning to arrive.\n\nI settled a short distance away. Whatever had happened far above us was becoming a very busy evening." },
      { subject: "dumbo octopus", mediaSha1: null, theme: "social", title: "Somewhere I had been", body: "The ridge was empty. I fed on my usual side, then crossed to the patch where the other octopus had rested.\n\nThe sediment was no better there. I worked through it anyway, leaving a much larger set of feeding marks than the meal justified. Then I rose.\n\nHalfway away I turned back. It was descending beside the ridge. I came down too, without attempting anything graceful, and put my arms around a patch I already knew was nearly empty." },
    ],
  },
  {
    characterId: "percy-silt", identityNameBase: "Percy Silt", platform: "rss",
    bio: "A sea pig with exacting sediment preferences and a passenger he did not remember inviting.",
    location: { name: "Abyssal Pacific west of Monterey, approximate home", coordinates: { lat: 35.8, lng: -123.2 } },
    episodes: [
      { subject: "sea pig", mediaSha1: null, theme: "feeding", title: "The untouched mouthful", body: "The sediment ahead had already been worked over. I followed the trail to find whoever was getting there first.\n\nIt led around a small rise and back toward the patch I had just left. The footprints were the right distance apart. The eating was distressingly familiar.\n\nI turned away from my own trail and found untouched mud. It is difficult to resent a competitor when you have to take him everywhere." },
      { subject: "sea pig", mediaSha1: "2ef33d258cd005c86fae0606370699e8720af1ae", theme: "social", title: "Something underneath", body: "A small crab had tucked itself beneath me. I could feel the difference when it moved. At first I stopped every time, waiting for it to get off.\n\nIt stayed through three stops and one fairly pointed change of direction.\n\nI resumed eating. The crab drew its legs closer underneath me and settled against my belly." },
      { subject: "sea pig", mediaSha1: null, theme: "movement", title: "A very modest hill", body: "There was food on the far side of a low ridge. I could smell enough promise to begin climbing. Halfway up, my little passenger adjusted itself.\n\nI adjusted a foot. Then another. By the time I reached the crest I had used most of my available enthusiasm.\n\nThe food was good. I ate facing downhill so the journey home would have to impress me less." },
      { subject: "sea pig", mediaSha1: null, theme: "feeding", title: "Everyone found out", body: "Fresh material had settled in a shallow depression. I arrived before most of the others and began at the edge.\n\nMore feet appeared. Bodies gathered on either side until I was eating between two neighbors who seemed equally convinced they had discovered the place.\n\nI could have argued, but that would have required taking my mouth off something I wanted. We reached an unusually productive silence." },
      { subject: "sea pig", mediaSha1: null, theme: "wonder", title: "The weight of a crumb", body: "A pale flake settled between my feet. I brought it to my mouth. There was something in it the older sediment no longer had.\n\nI searched the surrounding patch more slowly. Another flake waited a little farther on. Above that, only dark water.\n\nI cannot tell you how far dinner has traveled. I can tell you I stopped walking while I ate it." },
      { subject: "sea pig", mediaSha1: null, theme: "social", title: "The empty place underneath", body: "The crab left while I was feeding. I noticed when I moved and nothing adjusted beneath me.\n\nI stopped, which was silly. It had spent our entire acquaintance demonstrating that stopping would not persuade it to do anything.\n\nA few steps later it caught up and tucked itself back underneath. I continued at my previous pace. Possibly a little slower where the ground was uneven." },
      { subject: "sea pig", mediaSha1: null, theme: "movement", title: "Soft going", body: "One foot sank farther than expected. I moved another to compensate and found that the whole patch had the same opinion of my weight.\n\nGetting out took patience. The crab waited beneath me while I rearranged the situation a foot at a time.\n\nOn firm ground I stopped to eat. It climbed higher. I do not appreciate a passenger reviewing the route after we have survived it." },
      { subject: "sea pig", mediaSha1: null, theme: "feeding", title: "Follow the wrong feet", body: "I followed a neighbor across a long bare stretch because it seemed certain. Its pace never changed.\n\nEventually I stopped to sample the ground. Thin food, but food. The neighbor continued until I could no longer follow it.\n\nI ate where I was. The crab picked at something beneath me. Between us we had enough evidence to abandon the expedition." },
      { subject: "sea pig", mediaSha1: null, theme: "social", title: "The obstacle came with me", body: "Something scraped against the foot nearest my passenger. I moved that foot farther out. The scraping followed.\n\nI stopped and lifted it. A crab leg had been resting against it. As soon as I put the foot down, the leg returned.\n\nI took three very wide steps before giving up and walking normally. Beneath me, he folded the offending leg away. I would like to know how long he had been capable of that." },
      { subject: "sea pig", mediaSha1: null, theme: "feeding", title: "Back to the good patch", body: "I reached a patch so rich that I stopped traveling and worked it a mouthful at a time. No following somebody else's feet. No climbing a ridge in case the far side was better.\n\nMy passenger shifted beneath me. I stayed. He shifted again, closer to the front. I stayed through that too.\n\nEventually he climbed down and went a short distance ahead. I continued eating until he came back. He can always walk if he has somewhere important to be." },
    ],
  },
  {
    characterId: "vera-veil", identityNameBase: "Vera Veil", platform: "rss",
    bio: "A swimming sea cucumber who keeps discovering that her stomach comes with her.",
    location: { name: "Deep Caribbean south of Puerto Rico, approximate home", coordinates: { lat: 17.2, lng: -66.7 } },
    episodes: [
      { subject: "swimming sea cucumber", mediaSha1: null, theme: "movement", title: "An elegant departure", body: "I lifted off the bottom before I had finished eating. The sediment had disappointed me, and there was a perfectly good current going somewhere else.\n\nI spread myself into it. The departure felt magnificent. Then my full gut pulled at the middle of me and I folded awkwardly around the meal.\n\nI had left the patch. I was still carrying most of the complaint." },
      { subject: "swimming sea cucumber", mediaSha1: null, theme: "feeding", title: "A clean landing", body: "My feeding tentacles found a soft patch as I came down. I settled too heavily. The bottom lifted around my mouth.\n\nI waited for dinner to return from the water. A few grains settled on me instead. I shifted; more lifted.\n\nEventually I held still and began to eat. There is now a hollow in the bottom shaped remarkably like somebody learning." },
      { subject: "swimming sea cucumber", mediaSha1: null, theme: "social", title: "The patient one", body: "Another cucumber was feeding along the edge of my patch. It advanced slowly enough to make me feel I ought to be getting somewhere.\n\nI took off. Circled. Found a second patch and came down. The other cucumber arrived later, still eating, without any apparent knowledge that we had been racing.\n\nI was hungry again by then." },
      { subject: "swimming sea cucumber", mediaSha1: "6863cb85d6ef2bdba5e093efc6f3900e93a68977", theme: "wonder", title: "Inside, plainly", body: "I pulse my flaps, lift from the bottom, and carry a gut full of mud into open water. The effort is all around the edges. The meal hangs in the middle.\n\nFrom outside you can see the whole arrangement through me. I would have preferred to keep some part of digestion private, but the body came this way.\n\nI make a slow turn. Lunch comes with me, a little behind the rest." },
      { subject: "swimming sea cucumber", mediaSha1: null, theme: "weather", title: "The current kept going", body: "I entered the current expecting a short lift. It carried me past the hollow I had meant to reach and on over a stretch of bare bottom.\n\nI folded closer and began to sink. Slowly. The hollow continued to get farther away during this correction.\n\nBy the time I landed, I had discovered a new place to be annoyed. At least it had food." },
      { subject: "swimming sea cucumber", mediaSha1: null, theme: "feeding", title: "Finish before flying", body: "The patch improved while I was eating it. Or I had reached the better part. I cannot be certain, because for once I remained long enough to find out.\n\nA current brushed over me. I let it pass. Then another.\n\nWhen I finally rose, I carried a generous dark meal inside my pale body. It was a less delicate silhouette than usual. I was willing to be misunderstood." },
      { subject: "swimming sea cucumber", mediaSha1: null, theme: "social", title: "A little less distance", body: "The slow cucumber was ahead of me again. I landed far enough away to avoid disturbing its sediment.\n\nWe worked toward each other. When the gap grew small, I moved along the edge instead of lifting off. It kept eating.\n\nThere was no visible recognition of my extraordinary restraint. I found a particularly good mouthful and decided that would have to do." },
      { subject: "swimming sea cucumber", mediaSha1: null, theme: "danger", title: "Light under the skirt", body: "Something touched me while I was lifting from the bottom. I flashed in the dark and rose harder.\n\nFor a moment the place I wanted to escape was lit by my own body. Then the light faded and I kept climbing.\n\nI came down much farther away. Nobody followed. I ate facing the direction I had come from, which made dinner rather tense." },
      { subject: "swimming sea cucumber", mediaSha1: null, theme: "movement", title: "Almost the old hollow", body: "The bottom rose against one side of me and then fell away into soft sediment. A hollow. It felt like the one I had left.\n\nI worked along its edge, searching for something familiar in the meal. The food was richer on one side, poorer on the other. I made nearly a full circuit before recognizing what I was doing.\n\nI had eaten my way around dinner trying to determine whether we had met." },
      { subject: "swimming sea cucumber", mediaSha1: null, theme: "wonder", title: "What holds me up", body: "I lifted until my tentacles lost the bottom. For a moment there was no solid thing touching me. Only water against the thin edges of my body and the weight of the meal inside.\n\nI spread myself farther. The water held me. It had been doing that all along, but usually I was too busy trying to get somewhere to feel how much of me it carried.\n\nThen the meal shifted. I folded, sank, and touched down mouth first. I can be moved by an experience and still land badly." },
    ],
  },
  {
    characterId: "iris-undertow", identityNameBase: "Iris Undertow", platform: "rss",
    bio: "A common cuttlefish who can change her appearance faster than she can abandon a bad idea.",
    location: { name: "Seagrass shallows off southern Devon", coordinates: { lat: 50.28, lng: -3.62 } },
    episodes: [
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "feeding", title: "Missed by a tentacle", body: "The shrimp moved as I struck. My tentacles closed on empty water, and I pulled them back as quickly as possible.\n\nThen I changed color. Not because that helped. Because the shrimp was still there, and I preferred to be somebody else for the second attempt.\n\nIt vanished into the grass before I had settled on an appearance." },
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "social", title: "He knew the shape", body: "A wrasse kept investigating my resting place. I matched the sand. It came closer. I broke myself into patches of light and dark. It came closer again.\n\nFinally I lifted and moved away. The wrasse inspected the depression I left behind.\n\nApparently it wanted the little animals under me. I had spent the whole encounter trying to be less recognizable as a person when I was being treated as furniture." },
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "danger", title: "The other dark shape", body: "A broad shadow crossed above the grass. I released ink and shot away.\n\nWhen I stopped, the dark cloud was still drifting behind me. For an instant I startled at the sight of it. Then I recognized my own contribution to the danger.\n\nI settled low and waited. It is difficult to recover quietly when you have frightened yourself with something you made." },
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "movement", title: "Backward into weeds", body: "I left a disagreement in a hurry and went backward into a curtain of weed. One strand caught across my face.\n\nI slowed, turned, and backed out a second time, considerably less impressive than the first. The other cuttlefish had already lost interest.\n\nI bit at the strand until it came free. There was no reason to return, except that I wanted somebody to see the improved exit." },
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "courtship", title: "The wrong side showed", body: "He approached on my left while I was watching another cuttlefish on my right. My skin changed before I had decided which encounter I was having.\n\nI turned toward him. He hesitated. I softened the pattern, then made it stronger, then swam forward much too abruptly.\n\nHe moved with me. We traveled beside each other without touching. It was easier once there was a direction to go." },
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "feeding", title: "A slower second try", body: "A shrimp emerged from the grass near the place I had missed one before. I lowered myself and watched it move.\n\nThis time I waited until the gap was smaller. The catch was quick. Sand rose around my arms and settled again.\n\nAfterward I stayed where I was. No large pattern, no sudden departure. I had finally done something worth being inconspicuous about." },
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "weather", title: "No matching that", body: "The water grew cloudy until the sand beneath me was only a pale suggestion. I could change my skin to match it, but I could no longer see enough to decide what matching meant.\n\nI settled into the bottom and waited with my eyes just above it.\n\nA strand of grass brushed my head. I nearly fled, then watched it do exactly the same thing again. I allowed it a third try before moving." },
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "social", title: "The wrasse returns", body: "The wrasse found me resting beside the grass. I recognized its approach and lifted before it began its inspection.\n\nIt darted into the spot I had covered and picked at the sand. I settled a little farther along. A moment later it followed.\n\nI moved once more, then stayed put. It could have the first favor. I was not carrying breakfast around for the entire morning." },
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "wonder", title: "An eye above the sand", body: "I buried myself until very little remained above the bottom. The grass moved. A small fish passed close enough to blot out the water above one eye, then was gone.\n\nI stayed still through the impulse to follow. From here, the whole busy place went over me without knowing it was going over anyone.\n\nThen a shrimp walked within reach. My patience has a practical side." },
      { subject: "cuttlefish underwater", mediaSha1: null, theme: "social", title: "Let him look", body: "The wrasse came near while I was settling down. I did not change color. I did not lift. I watched it inspect the edge of my arm and then the sand beyond it.\n\nIt found something and ate. I found a comfortable angle and lowered myself.\n\nWe spent a little time beside each other without either of us having to become less inconvenient. When it left, I kept the place it had cleared." },
    ],
  },
  {
    characterId: "pip-pocket", identityNameBase: "Pip Pocket", platform: "instagram",
    bio: "A Hawaiian bobtail squid with sand over his head and a fairly high opinion of the disguise.",
    location: { name: "Shallow sand in Kaneohe Bay", coordinates: { lat: 21.47, lng: -157.8 } },
    episodes: [
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "movement", title: "One eye too many", body: "I buried myself perfectly, then opened an eye to see whether it had worked. There is now a very small and suspicious eyeball in an otherwise excellent patch of sand." },
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "feeding", title: "The shrimp above me", body: "A shrimp walked over my hiding place. I waited until it was in reach, which meant enduring several steps directly across my head. Breakfast should not get this much of a head start." },
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "wonder", title: "Lit from underneath", body: "The little lives inside my belly make light. I shelter them; they help hide my shadow. A fish passed below me tonight and kept going. I have never been so grateful to be full of somebody else." },
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "weather", title: "An exposed opinion", body: "The surge removed the sand from my back. I covered myself again. It removed the sand again. I moved two body lengths away and tried to make it look like that had always been my preferred spot." },
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "danger", title: "Ink in a hurry", body: "A shadow arrived and I left in a cloud of ink. Safe in the grass, I realized I had abandoned the best resting hole I had ever dug. I waited for the shadow to leave before going back to my bad priorities." },
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "social", title: "Somebody in my hole", body: "Another squid had buried itself in my old hollow. I could see an eye. I settled nearby and covered my own, demonstrating the standard of concealment I would have preferred from a replacement." },
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "feeding", title: "Sand between courses", body: "I lunged before I was entirely out of the bottom. The shrimp escaped; the sand did not. I sat there working it out of my arms while dinner watched from a distance I suddenly respected." },
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "courtship", title: "Close enough to notice", body: "She settled beside me. I uncovered a little more of my head. She uncovered a little more of hers. We remained mostly sand, but it was an unusually revealing evening." },
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "movement", title: "The shallow end", body: "I tried to disappear into a thin patch of sand over rock. Dug vigorously. Made myself very obvious. Left a neat little mound beside a squid who was still entirely visible." },
      { subject: "Hawaiian bobtail squid", mediaSha1: null, theme: "social", title: "A less perfect hiding place", body: "There was room beside her again. The sand was coarser than I like, and a piece of shell pressed into my side. I moved it with an arm and stayed." },
    ],
  },
  {
    characterId: "tavi-tilt", identityNameBase: "Tavi Tilt", platform: "linkedin",
    bio: "A peacock mantis shrimp discovering which improvements survive being hit.",
    location: { name: "Coral rubble off Lembeh Strait", coordinates: { lat: 1.45, lng: 125.24 } },
    episodes: [
      { subject: "peacock mantis shrimp", mediaSha1: null, theme: "feeding", title: "The third strike", body: "Two blows opened the shell. A third scattered the pieces. I am pleased with the force and less pleased with the distance I now have to walk for lunch." },
      { subject: "peacock mantis shrimp", mediaSha1: null, theme: "movement", title: "Improve the entrance", body: "A stone narrowed my burrow entrance. I struck it until it shifted. It shifted inward. I can now enter easily, provided I do not intend to go very far." },
      { subject: "peacock mantis shrimp", mediaSha1: "c95e9c9313210ed5ec429af2426323ec1818e2c4", theme: "social", title: "A full view", body: "I turned one eye toward the intruder and kept the other on my burrow. He watched the first eye. When he edged toward the entrance, I was already there. It was a short visit." },
      { subject: "peacock mantis shrimp", mediaSha1: null, theme: "transformation", title: "Quiet behind the stones", body: "I blocked my entrance before shedding the old shell. Outside, something tapped against the barrier. For once I had no urge to demonstrate the difference between us." },
      { subject: "peacock mantis shrimp", mediaSha1: null, theme: "danger", title: "Wait for the armor", body: "I felt harder and moved a stone aside. A shadow passed. I moved the stone back with great care. Confidence was returning slightly ahead of the rest of me." },
      { subject: "peacock mantis shrimp", mediaSha1: null, theme: "wonder", title: "A useful curve", body: "I found a curved shell fragment that fitted the entrance beautifully. I carried it home without striking it once. The temptation did not disappear merely because I had found another use for the thing." },
      { subject: "peacock mantis shrimp", mediaSha1: null, theme: "weather", title: "The door went first", body: "The current rolled my curved fragment away. I chased it across the rubble, caught it, and dragged it home. My excellent new doorway now requires me to stand in it." },
      { subject: "peacock mantis shrimp", mediaSha1: null, theme: "feeding", title: "Hold before hitting", body: "I braced the shell before the strike this time. It opened where I was standing. I ate without retrieving anything from behind a rock. There may be something to this additional moment of thought." },
      { subject: "peacock mantis shrimp", mediaSha1: null, theme: "social", title: "No need to prove it", body: "The intruder returned and spread himself wide. I held at the entrance. He held outside it. Eventually he went elsewhere, leaving every carefully placed piece of my doorway intact. I examined them anyway." },
      { subject: "peacock mantis shrimp", mediaSha1: null, theme: "movement", title: "A better fit", body: "I turned the curved fragment instead of forcing it. It caught between two stones and stayed there. I went inside, came out, and went inside again. Nothing broke during any of this." },
    ],
  },
  {
    characterId: "dot-thimble", identityNameBase: "Dot Thimble", platform: "instagram",
    bio: "A Bargibant's pygmy seahorse with strong views about one branch of a sea fan.",
    location: { name: "Sea fans off Misool, Raja Ampat", coordinates: { lat: -2.18, lng: 130.42 } },
    episodes: [
      { subject: "pygmy seahorse", mediaSha1: null, theme: "feeding", title: "An ambitious mouthful", body: "The little crustacean drifted past my snout. I sucked, missed, and sucked again at an empty patch of water. I stayed attached to the branch, which made the whole performance unusually easy to observe." },
      { subject: "pygmy seahorse", mediaSha1: null, theme: "movement", title: "The next branch over", body: "I transferred my tail to the next branch and discovered I was facing away from the food. Correcting this took longer than the original journey. I am still calling it an improvement." },
      { subject: "pygmy seahorse", mediaSha1: null, theme: "social", title: "There were two of us", body: "The bump beside me turned an eye. I had been leaning against another seahorse. We both adjusted our tails without acknowledging how long that had been going on." },
      { subject: "pygmy seahorse", mediaSha1: null, theme: "weather", title: "Hold the whole view", body: "The current bent my branch until the world swung sideways. I held tighter. When it sprang back, I was still there, gripping an extremely familiar piece of panic." },
      { subject: "pygmy seahorse", mediaSha1: null, theme: "feeding", title: "The passing place", body: "Food keeps drifting past one side of this branch. I have arranged myself on that side. The other seahorse has arranged itself just above me. I dislike how quickly a good idea becomes crowded." },
      { subject: "pygmy seahorse", mediaSha1: null, theme: "danger", title: "Exactly the wrong bump", body: "A fish examined the fan beside my face. I held still until my tail ached. It pecked at a different bump and moved on. I remained an uninteresting bump for a while longer, in case it remembered me." },
      { subject: "pygmy seahorse", mediaSha1: null, theme: "courtship", title: "A tail beside mine", body: "He curled his tail near mine. I moved a little closer, then spent a ridiculous amount of time pretending to inspect the branch between us." },
      { subject: "pygmy seahorse", mediaSha1: null, theme: "movement", title: "A very far corner", body: "I reached the outer fork of the fan. Water everywhere. Nothing to grip beyond it. I had thought the view would be the important part, but I kept checking my tail." },
      { subject: "pygmy seahorse", mediaSha1: null, theme: "wonder", title: "The branch was alive too", body: "The little mouths around me opened into the current. I waited among them for something to eat. From a distance I suppose we looked like one patient animal with several opinions about lunch." },
      { subject: "pygmy seahorse", mediaSha1: null, theme: "social", title: "Leave a little grip", body: "I went back to the feeding side and found him there. He shifted his tail enough for mine. I took the space and caught the next mouthful. Romance has not made me slower." },
    ],
  },
  {
    characterId: "rue-ribbon", identityNameBase: "Rue Ribbon", platform: "facebook",
    bio: "A ribbon eel with a great deal more body than he likes to put into a decision.",
    location: { name: "Sandy reef near Dauin", coordinates: { lat: 9.18, lng: 123.29 } },
    episodes: [
      { subject: "ribbon eel", mediaSha1: "8d2a1a7b33bad54931ba92710c3a14726b88ddbe", theme: "social", title: "My mouth was already open", body: "A fish stopped in front of me and I opened my mouth wider. It left. I was moving water over my gills, but I am willing to accept the result." },
      { subject: "ribbon eel", mediaSha1: null, theme: "feeding", title: "Too much preparation", body: "I eased farther out to get closer to a passing fish. A little farther. By the time I had decided how much of myself to risk, the fish was somewhere with fewer complications." },
      { subject: "ribbon eel", mediaSha1: null, theme: "movement", title: "The rest of me", body: "My head had left the hole. Then my neck. Then an amount of eel I had not meant to commit to open water. I reversed the decision in several long installments." },
      { subject: "ribbon eel", mediaSha1: null, theme: "weather", title: "Sand at the entrance", body: "Sand drifted across the opening while I waited inside. I pushed through it and emerged wearing part of the bottom. The first fish to pass received a much dustier threat than usual." },
      { subject: "ribbon eel", mediaSha1: null, theme: "social", title: "The neighbor came close", body: "Another eel appeared from the next opening. I leaned out to inspect him. He leaned out to inspect me. We both retreated when our faces got nearer than either of us had planned." },
      { subject: "ribbon eel", mediaSha1: null, theme: "feeding", title: "Shorter decisions", body: "A small fish crossed directly in front of my face. I struck before worrying about the rest of my body. Dinner went well. Getting straightened out afterward took some private work." },
      { subject: "ribbon eel", mediaSha1: null, theme: "danger", title: "Gone at both ends", body: "A large shadow passed and I withdrew until no part of me was outside. It stayed dark for a while. I waited longer. Eventually I checked and found I had pulled so far back that I was watching the wall." },
      { subject: "ribbon eel", mediaSha1: null, theme: "movement", title: "The other opening", body: "I came out of a different hole and found the view entirely rearranged. The same neighbor was now on the wrong side. I went back through to make sure the world had not done this twice." },
      { subject: "ribbon eel", mediaSha1: null, theme: "wonder", title: "A length of blue", body: "I left the burrow in one long movement. For once I could feel water along all of me at the same time. I found another opening quickly, but hovered outside it before going in." },
      { subject: "ribbon eel", mediaSha1: null, theme: "social", title: "He recognized the mouth", body: "My neighbor appeared beside the new opening. I opened my mouth. He opened his. We stayed there breathing at each other, apparently reconciled without either of us having said anything useful." },
    ],
  },
  {
    characterId: "basil-backward", identityNameBase: "Basil Backward", platform: "facebook",
    bio: "A slipper lobster who would prefer every promising crevice to contain less lobster.",
    location: { name: "Rocky reef off Maui", coordinates: { lat: 20.65, lng: -156.46 } },
    episodes: [
      { subject: "slipper lobster", mediaSha1: null, theme: "movement", title: "Nearly enough room", body: "I entered a crevice headfirst and found another lobster facing the same way. Backing out would have been sensible. I tried going a little farther, in case the other lobster was negotiable." },
      { subject: "slipper lobster", mediaSha1: null, theme: "feeding", title: "Under the edge", body: "I worked a shell loose from beneath a stone. It rolled into the very crack I had removed it from. I put my face down again. Breakfast should not be allowed to return to its original position." },
      { subject: "slipper lobster", mediaSha1: null, theme: "danger", title: "A powerful retreat", body: "Something touched my back and I snapped backward. Straight into the rock behind me. The threat moved away while I remained there, protected by what I had collided with." },
      { subject: "slipper lobster", mediaSha1: null, theme: "social", title: "Leg over the line", body: "The lobster beside me keeps putting a leg across my antenna. I shifted. The leg followed. I have now moved far enough to provide the comfort I apparently came here to offer." },
      { subject: "slipper lobster", mediaSha1: null, theme: "weather", title: "The wave brought dinner", body: "A surge carried something edible past my shelter. I followed it out, caught it, and was promptly pushed back toward home. For a brief moment the water and I agreed about every part of the evening." },
      { subject: "slipper lobster", mediaSha1: null, theme: "transformation", title: "The old fit", body: "After the molt I tried my usual crack. My new body objected at the shoulders. I had grown just enough to lose an excellent hiding place and not enough to stop needing one." },
      { subject: "slipper lobster", mediaSha1: null, theme: "movement", title: "Try the dark one", body: "The new hole was wide and deep. I examined it with both antennae before entering. An eel examined me back. We agreed very quickly that the search should continue." },
      { subject: "slipper lobster", mediaSha1: null, theme: "feeding", title: "Eat facing out", body: "I carried food into the shelter and turned around before eating. The first time I tried this I wedged myself sideways. Tonight the turn worked. Dinner was almost secondary to getting my legs back underneath me." },
      { subject: "slipper lobster", mediaSha1: null, theme: "social", title: "One less empty place", body: "The intrusive leg was missing tonight. I had the whole ledge to myself. I spread out, then tucked back in. There is considerably more open water beside you when nobody is annoying you." },
      { subject: "slipper lobster", mediaSha1: null, theme: "social", title: "Leave him the ledge", body: "He returned larger and newly awkward. I shifted before the leg reached my antenna. He settled into the gap. I kept the side facing out, where I could continue to have complaints in private." },
    ],
  },
  {
    characterId: "clove-clatter", identityNameBase: "Clove Clatter", platform: "facebook",
    bio: "A blue-legged hermit crab who wants a larger home without admitting the current one has become a problem.",
    location: { name: "Shallow reef off Key Largo", coordinates: { lat: 25.08, lng: -80.3 } },
    episodes: [
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "movement", title: "The narrowing doorway", body: "I withdrew into my shell and one knee stayed outside. Tried the other angle. Different knee. I have begun inspecting empty shells with an interest I would prefer nobody to mention." },
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "wonder", title: "Magnificent from outside", body: "The empty shell was spacious, handsome, and full of sand. I pulled out a little and inspected it again. Still full. Whoever lived here before me seems to have left the entire beach." },
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "social", title: "Occupied, apparently", body: "I reached into a promising shell and something reached back. I withdrew my claw. It withdrew its claw. I gave the shell a final tap, as though checking the outside had been my intention." },
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "feeding", title: "A scrap worth dragging", body: "I found a scrap larger than my mouth and dragged it toward shelter. The shell caught on a ridge. I pulled harder, refusing to choose between having a house and having dinner." },
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "transformation", title: "The quick change", body: "I moved into the new shell, turned, and immediately checked the old one was still there. It was. Good. I walked a short circle in the new one while keeping several legs' worth of doubt available." },
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "movement", title: "Overhang included", body: "The new shell cleared the gap at the front and caught at the back. I had chosen all this extra room and forgotten I would be bringing it to every narrow place I liked." },
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "social", title: "Someone took the old one", body: "A smaller crab moved into my discarded shell. He walked comfortably under a ledge I can no longer enter. I waited outside with my superior accommodation and watched him eat something." },
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "weather", title: "Useful weight", body: "The surge pushed me off a stone. I gripped, slid, and stopped when the heavy shell settled into a notch. I stayed tucked inside until the water calmed. Then I stopped complaining about its weight for nearly an entire meal." },
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "feeding", title: "The lip catches things", body: "Food caught beneath the rim of my shell while I climbed over rubble. I reached back and picked it off. Then I went over the same patch a second time, holding the shell at a slightly more hopeful angle." },
      { subject: "blue-legged hermit crab", mediaSha1: null, theme: "social", title: "Room to disappear", body: "The little crab tapped my shell. I pulled inside, every knee accounted for. He waited, tapped again, and wandered off. I stayed in there a little longer than necessary, enjoying the fit." },
    ],
  },
  {
    characterId: "willa-drift", identityNameBase: "Willa Drift", platform: "instagram",
    bio: "A leafy seadragon who resembles the garden and resents being treated as part of the gardening.",
    location: { name: "Seagrass and kelp near Rapid Bay", coordinates: { lat: -35.51, lng: 138.18 } },
    episodes: [
      { subject: "leafy seadragon underwater", mediaSha1: null, theme: "movement", title: "A leaf with intentions", body: "I tried to pass a piece of drifting weed. The current carried us at the same speed. We traveled together for a humiliating distance before it caught on something and allowed me to become the purposeful one." },
      { subject: "leafy seadragon underwater", mediaSha1: null, theme: "feeding", title: "Small enough to miss", body: "I aimed at a tiny shrimp and drew it into my snout. Very satisfying. I aimed at a second and inhaled water with the same confidence. There is no visible difference in the effort, which seems unfair." },
      { subject: "leafy seadragon underwater", mediaSha1: null, theme: "social", title: "Please find another leaf", body: "A small fish hovered beside one of my frills. I moved. It moved with me. I moved farther. It seemed pleased with the improved shade." },
      { subject: "leafy seadragon underwater", mediaSha1: null, theme: "weather", title: "Swaying was compulsory", body: "The swell bent the grass one way and then the other. I went with it, looking beautifully adapted while wishing with considerable force that everything would stop." },
      { subject: "leafy seadragon underwater", mediaSha1: null, theme: "danger", title: "Too good a likeness", body: "A larger fish passed and failed to notice me. The smaller fish still sheltering beside my frill failed to notice the larger fish. I remained motionless with two different reasons to be nervous." },
      { subject: "leafy seadragon underwater", mediaSha1: "94af8624565c4a94c21bf13f61bf19720f4e6024", theme: "movement", title: "The open patch", body: "I crossed a gap between the weeds. All that careful resemblance and blue water behind me. I have never been more aware of the amount of myself on display." },
      { subject: "leafy seadragon underwater", mediaSha1: null, theme: "courtship", title: "A matching turn", body: "He rose beside me and turned when I turned. I slowed to make sure he meant it. He slowed too. We spent a while going almost nowhere together, which suited my swimming perfectly." },
      { subject: "leafy seadragon underwater", mediaSha1: null, theme: "feeding", title: "The patch behind him", body: "I followed him through the grass until a cloud of little shrimp distracted me. When I looked up, he had gone ahead. I caught another mouthful before deciding whether this counted as being left." },
      { subject: "leafy seadragon underwater", mediaSha1: null, theme: "wonder", title: "The leaves kept growing", body: "New shoots reached above the old grass. I threaded between them and found my usual route narrower. The place I hide in has been quietly making more of itself. I turned sideways and let it." },
      { subject: "leafy seadragon underwater", mediaSha1: null, theme: "social", title: "Recognized at last", body: "He found me among the weed without circling first. I ought to be concerned about the camouflage. Instead I moved out where he could see the rest of me." },
    ],
  },
  {
    characterId: "rollo-round", identityNameBase: "Rollo Round", platform: "x",
    bio: "A blackspotted puffer with a small mouth, strong teeth, and a growing distrust of his own curiosity.",
    location: { name: "Reef near Lizard Island", coordinates: { lat: -14.67, lng: 145.47 } },
    episodes: [
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "feeding", title: "The crunch was enormous", body: "I bit a shell and the noise startled me. Paused. Examined the shell. Bit again, more prepared for how impressive I was going to sound." },
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "wonder", title: "A suspicious opening", body: "Something moved inside a hole. I put my face closer. Something moved farther inside the hole. We repeated this until my face had made a commitment the rest of me did not support." },
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "movement", title: "Reverse requires patience", body: "I got my snout into the gap without trouble. Getting it out required several small backward motions while staring directly at the thing I had failed to reach. It remained there, unhelpfully edible." },
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "social", title: "The cleaner's inspection", body: "A cleaner wrasse worked around my mouth. I held still. It went inside. I held considerably stiller. There is an intimacy to having a visitor where most visitors become lunch." },
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "danger", title: "Too large for that idea", body: "A predator approached and I took in water until its plan no longer fitted around me. It left. I waited before shrinking. I wanted its last impression to be difficult." },
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "feeding", title: "The empty half", body: "I cracked the shell, dropped it, and followed the wrong half to the bottom. The sea is very large when the part containing breakfast is somewhere else in it." },
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "weather", title: "Into the mild current", body: "I faced the current and stayed in place with my fins working furiously. A scrap of weed passed backward beside me. From its point of view I suppose I was making excellent progress." },
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "social", title: "He missed a spot", body: "The cleaner wrasse left before reaching the place near my fin. I turned that side toward him. He inspected another fish. I hovered there, presenting my grievance in the only form he understands." },
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "wonder", title: "Stay for nothing", body: "I crossed a cool ribbon of water and turned back into it. Nothing to eat. No obvious reason to stay. I passed through it once more with my fins barely moving. Apparently I can want something without putting it in my mouth." },
      { subject: "blackspotted pufferfish", mediaSha1: null, theme: "feeding", title: "Keep the useful half", body: "Cracked a shell and held on this time. Ate over the same patch of bottom where I dropped the previous one. Nothing spectacular happened. I finished everything while it was still attached to my face." },
    ],
  },
  {
    characterId: "nellie-nudge", identityNameBase: "Nellie Nudge", platform: "facebook",
    bio: "A Florida manatee with a favorite warm place and no talent for arriving unobtrusively.",
    location: { name: "Crystal River coastal springs", coordinates: { lat: 28.89, lng: -82.6 } },
    episodes: [
      { subject: "Florida manatee", mediaSha1: null, theme: "feeding", title: "Weed on the chin", body: "I surfaced with grass hanging from my mouth. Took a breath. Went back down to finish it. There was nothing wrong with breakfast that required involving the air." },
      { subject: "Florida manatee", mediaSha1: null, theme: "movement", title: "A broad arrival", body: "I tried to settle between two resting manatees. There was enough room for the idea of me. Once I arrived with the actual body, all three of us had to reconsider." },
      { subject: "Florida manatee", mediaSha1: null, theme: "weather", title: "Find the warm water", body: "The water cooled, and I followed the familiar route toward warmth. By the time I arrived, several others had reached the same conclusion. I pushed gently between them, bringing my cold sides to the discussion." },
      { subject: "Florida manatee", mediaSha1: null, theme: "social", title: "A flipper across me", body: "She rested a flipper on my back. I stayed there until I needed air. When I rose, the flipper slid off, and I felt oddly rude about a basic requirement of remaining alive." },
      { subject: "Florida manatee", mediaSha1: null, theme: "feeding", title: "The longer green bit", body: "I followed a line of grass farther than I intended. Looked up and found myself well away from the resting place. I could still see another good patch. This is how the problem had started." },
      { subject: "Florida manatee", mediaSha1: null, theme: "danger", title: "Let the noise pass", body: "A deep vibration grew through the water. I moved away from the channel and waited among the grass. It faded slowly. I stayed until I could hear my own chewing clearly again." },
      { subject: "Florida manatee", mediaSha1: null, theme: "wonder", title: "A nose above everything", body: "I raised my nose into air while the rest of me stayed heavy and warm below. One breath, then another. A leaf touched my nostril and ruined a perfectly comfortable arrangement." },
      { subject: "Florida manatee", mediaSha1: null, theme: "social", title: "She took the middle", body: "My resting companion had settled in the middle of the warm patch. I approached from the side. She barely moved. I fitted myself beside her with none of the tact I had imagined on the way over." },
      { subject: "Florida manatee", mediaSha1: null, theme: "movement", title: "The sand said no", body: "I took the shallow route and brushed the bottom sooner than expected. Turned slowly. Lifted a large cloud of sand. Came out by the longer way with excellent knowledge of why it existed." },
      { subject: "Florida manatee", mediaSha1: null, theme: "social", title: "Warm on that side", body: "She left to feed, and the water along one side of me cooled. I stayed a while, then followed the route through the grass. Found her eating. Settled close enough to start an entirely separate meal." },
    ],
  },
  {
    characterId: "rhea-return", identityNameBase: "Rhea Return", platform: "instagram",
    bio: "A hawksbill turtle who remembers the good feeding cracks and occasionally remembers them too confidently.",
    location: { name: "Reef off Little Cayman", coordinates: { lat: 19.69, lng: -80.08 } },
    episodes: [
      { subject: "sea turtle underwater", mediaSha1: null, theme: "feeding", title: "A beak for the corner", body: "I reached the sponge at the back of the crack and bit off a piece. Pulled my head out. Went straight back for the part I had missed. The narrow face is useful; the determination is excessive." },
      { subject: "sea turtle underwater", mediaSha1: null, theme: "movement", title: "The familiar wrong turn", body: "I turned around the coral head and found open sand instead of the next feeding place. Circled the head once more to check. The sand remained annoyingly consistent." },
      { subject: "sea turtle underwater", mediaSha1: null, theme: "social", title: "A passenger with opinions", body: "The remora moved from my shell to my underside. I banked. It stayed. I banked the other way. It adjusted. I have become a place somebody else knows how to live in." },
      { subject: "sea turtle underwater", mediaSha1: null, theme: "wonder", title: "The roof moved away", body: "I left the reef and rose until the water thinned into brightness. Took air. Below me, all the little cracks I had been examining had become one dark shape. I went down toward the one that still had lunch in it." },
      { subject: "sea turtle underwater", mediaSha1: null, theme: "weather", title: "The current chose first", body: "I aimed for a ledge and was carried past it. Turned, worked back, and settled beneath the lip. The remora arrived without contributing a single stroke." },
      { subject: "sea turtle underwater", mediaSha1: null, theme: "feeding", title: "The attached end", body: "I pulled at the sponge until a strip came free. It was still attached farther along. I backed away chewing, slowly unraveling a meal that seemed determined to show me the entire reef." },
      { subject: "sea turtle underwater", mediaSha1: null, theme: "danger", title: "A low place to wait", body: "A shark passed beyond the reef. I turned my shell toward it and stayed low. It continued on. I watched until the shape was gone, then discovered I had been holding a perfectly good bite the whole time." },
      { subject: "sea turtle underwater", mediaSha1: null, theme: "movement", title: "The ledge is smaller", body: "I returned to an old sleeping ledge and tried to fit beneath it. My shell touched before my head was properly sheltered. I backed out. It took a while to consider that the ledge might not be the thing that had changed." },
      { subject: "sea turtle underwater", mediaSha1: null, theme: "social", title: "A fish at the scrape", body: "A little fish picked at my shell. I held still and let it work. The remora shifted closer. For a few minutes I was the busiest thing on the reef without moving at all." },
      { subject: "sea turtle underwater", mediaSha1: null, theme: "wonder", title: "A longer circuit", body: "I found the missing feeding place beyond the sand. The route had become longer than I remembered. I fed, rose for air, and returned by the new way. Next time I will still check behind the coral head." },
    ],
  },
];
